// The Sable watch face, in Watch Face Format (WFF): XML and images, no code. Wear OS draws it,
// which is cheaper on the battery than a face that runs its own code.
// res/raw/watchface.xml is generated by tools/gen-watchface.py.
plugins {
    id("com.android.application")
}

android {
    namespace = "io.github.aimindseye.sablewatch.face"
    compileSdk = 36

    defaultConfig {
        applicationId = "io.github.aimindseye.sablewatch.face"
        // Watch Face Format v1 needs Wear OS 4 (API 33) or later.
        minSdk = 33
        targetSdk = 34
        versionCode = 1
        versionName = "0.1.0"
    }

    buildTypes {
        release {
            // A WFF face has no code to shrink.
            isMinifyEnabled = false
            signingConfig = null
        }
    }
}
